window.MG_LAZY_DATA["data/lazy/owner-courses/b304-4eaa61a554a1e9a1.json"]={sha256:"4eaa61a554a1e9a1a24be1dda3de24ff1fe38d60bd205eb858f7ce494541a5d0",value:{"id":"b304","title":"高雄捷運紅線","titleEn":"Kaohsiung MRT Red Line","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"以高雄紅線的南北都市走廊為背景，建立炎熱午後的站車負載案例。學徒需把冷房耗電、尖峰上車與加速電流放在同一時間軸，並在強降雨與單一電源失效下檢查服務降級和人員引導。","summaryEn":"Use Kaohsiung’s north-south Red Line as the setting for a hot-afternoon station and train load case. Place cooling demand, peak boarding and acceleration current on one timeline. Under heavy rainfall and a single supply failure, examine degraded service and passenger guidance without assuming that comfortable room temperature alone demonstrates system resilience.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-metro","subcategoryTitle":"都會捷運與貨運","subcategoryTitleEn":"Urban metros and freight","learningTrack":"rail","learningSubdiscipline":"rail-metro","learningTags":["rail","rail-metro","station"],"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]],"diagram":{"type":"rail-system","labels":["路線與土建","車輛與接觸","牽引供電","行車控制","車站與旅客"],"labelsEn":["Alignment and civil works","Vehicle and contact","Traction supply","Movement control","Stations and passengers"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 air_rise=12.81095 K；單元 2 得 capacity=17475.73 persons/hour；單元 3 得 dwell=24.86458 s。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 heat 的擾動測試，結果改為 14.09204 K；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以高雄紅線的南北都市走廊為背景，建立炎熱午後的站車負載案例。學徒需把冷房耗電、尖峰上車與加速電流放在同一時間軸，並在強降雨與單一電源失效下檢查服務降級和人員引導。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives air_rise=12.81095 K; unit 2 gives capacity=17475.73 persons/hour; unit 3 gives dwell=24.86458 s. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing heat in the first unit changes its result to 14.09204 K. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use Kaohsiung’s north-south Red Line as the setting for a hot-afternoon station and train load case. Place cooling demand, peak boarding and acceleration current on one timeline. Under heavy rainfall and a single supply failure, examine degraded service and passenger guidance without assuming that comfortable room temperature alone demonstrates system resilience. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b304-v16-s1","title":"通風散熱與設備溫升與班距與有效運能","titleEn":"Ventilation cooling and equipment heat & Headway and usable capacity","description":"本階段聚焦「通風散熱與設備溫升」與「班距與有效運能」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Ventilation cooling and equipment heat\" and \"Headway and usable capacity\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b304-v16-01","title":"通風散熱與設備溫升：機制與系統路徑","titleEn":"Ventilation cooling and equipment heat: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":[],"objective":"說明「通風散熱與設備溫升」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Ventilation cooling and equipment heat” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"流動空氣帶走的顯熱與質量流率和溫升相乘，風量不足會提高排氣溫度。設備房還存在短路循環和局部熱點，平均送排風溫差不能保證所有電子模組都在同樣環境中。 顯熱負載決定溫度改變需求，但高濕環境還有潛熱除濕與新風處理。冷卻量和耗電量也不同，兩者需要效率或性能係數連結，不能把熱量數字當作電表讀值。 把月台與車廂顯熱負載分開，避免用總冷量代替區域舒適度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「通風散熱與設備溫升」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Air removes sensible heat through mass flow and temperature rise. Insufficient flow raises exhaust temperature. Equipment rooms also contain recirculation and hot spots, so an average supply-to-exhaust difference does not guarantee identical conditions around every electronic module. Sensible load describes temperature-related demand, while humidity introduces latent dehumidification and outdoor-air treatment. Cooling delivered and electricity consumed are different quantities, connected through efficiency or a performance coefficient rather than treated as identical meter readings. Separate platform and carriage sensible loads instead of substituting total cooling for local comfort. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Ventilation cooling and equipment heat” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s；計算：air_rise=heat/(density*cp*flow)=12.81095 K。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s; calculation: air_rise=heat/(density*cp*flow)=12.81095 K.","failure":"常見誤解：「風機轉速正常就能保證機櫃內每個設備都有足夠散熱」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Normal fan speed guarantees adequate cooling for every device in the cabinet.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「通風散熱與設備溫升」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Ventilation cooling and equipment heat”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-01-k1","title":"通風散熱與設備溫升","titleEn":"Ventilation cooling and equipment heat","text":"流動空氣帶走的顯熱與質量流率和溫升相乘，風量不足會提高排氣溫度。設備房還存在短路循環和局部熱點，平均送排風溫差不能保證所有電子模組都在同樣環境中。","textEn":"Air removes sensible heat through mass flow and temperature rise. Insufficient flow raises exhaust temperature.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：風機轉速正常就能保證機櫃內每個設備都有足夠散熱 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Normal fan speed guarantees adequate cooling for every device in the cabinet. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「通風散熱與設備溫升」，下列哪一項敘述正確？","questionEn":"Which statement about \"Ventilation cooling and equipment heat\" is correct?","options":["風機轉速正常就能保證機櫃內每個設備都有足夠散熱","流動空氣帶走的顯熱與質量流率和溫升相乘，風量不足會提高排氣溫度。","只要平均班距減半所有乘客的等待時間就一定減半"],"optionsEn":["Normal fan speed guarantees adequate cooling for every device in the cabinet.","Air removes sensible heat through mass flow and temperature rise.","Halving average headway necessarily halves the waiting time of every passenger."],"answer":1,"explanation":"流動空氣帶走的顯熱與質量流率和溫升相乘，風量不足會提高排氣溫度。 其餘選項是常見誤解。","explanationEn":"Air removes sensible heat through mass flow and temperature rise. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b304-v16-02","title":"通風散熱與設備溫升：定量估算","titleEn":"Ventilation cooling and equipment heat: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-01"],"objective":"以數值模型估算「通風散熱與設備溫升」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Ventilation cooling and equipment heat” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s；計算：air_rise=heat/(density*cp*flow)=12.81095 K。敏感度：heat 單獨增加百分之十至 20394 W，其餘固定，結果為 14.09204 K。模型邊界：穩態顯熱且混合均勻；不含潛熱、輻射與空調循環效率。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s; calculation: air_rise=heat/(density*cp*flow)=12.81095 K. Sensitivity: heat, increase this input alone by ten percent, to 20394 W, with all other inputs fixed, gives 14.09204 K. Model boundary: Steady sensible heat and uniform mixing; latent heat, radiation and refrigeration-cycle efficiency are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同時量送風量、進出口溫度和設備用電，沿機櫃高度布置測點，確認冷風沒有直接繞過設備流回出口。","observationEn":"How to cross-check: Measure supply flow, inlet and outlet temperatures and electrical load together, instrument cabinet height, and check that cold air does not bypass the equipment.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s；計算：air_rise=heat/(density*cp*flow)=12.81095 K。敏感度：heat 單獨增加百分之十至 20394 W，其餘固定，結果為 14.09204 K。模型邊界：穩態顯熱且混合均勻；不含潛熱、輻射與空調循環效率。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s; calculation: air_rise=heat/(density*cp*flow)=12.81095 K. Sensitivity: heat, increase this input alone by ten percent, to 20394 W, with all other inputs fixed, gives 14.09204 K. Model boundary: Steady sensible heat and uniform mixing; latent heat, radiation and refrigeration-cycle efficiency are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「通風散熱與設備溫升」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Ventilation cooling and equipment heat\", which statement holds?","options":["用平均電流代入平方損耗公式總能得到正確熱負荷","只要列車裝有再生煞車全部動能都能回到電網","原創假想算例，全部輸入均非本工程操作參數：heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s。"],"optionsEn":["Squaring average current always gives the correct resistive heat load.","Installing regenerative braking returns all train kinetic energy to the supply network.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s；計算：air_rise=heat/(density*cp*flow)=12.81095 K。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: heat=18540 W; density=1.2 kg/m^3; cp=1005 J/(kg*K); flow=1.2 m^3/s; calculation: air_rise=heat/(density*cp*flow)=12.81095 K. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b304-v16-03","title":"通風散熱與設備溫升：試驗與驗證","titleEn":"Ventilation cooling and equipment heat: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「通風散熱與設備溫升」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Ventilation cooling and equipment heat” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同時量送風量、進出口溫度和設備用電，沿機櫃高度布置測點，確認冷風沒有直接繞過設備流回出口。 同步量測進出風溫度、流量和耗電，另記濕度與新風比例，確認顯熱邊界一致。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Measure supply flow, inlet and outlet temperatures and electrical load together, instrument cabinet height, and check that cold air does not bypass the equipment. Measure inlet and outlet air temperature, airflow and electricity together, separately recording humidity and outdoor-air fraction to confirm consistent sensible boundaries. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較降低風量與增加設備負載兩種情況，建立溫升敏感度表，再選出能辨別旁通流和真正熱負荷增加的測點。 再以本單元 heat 的對照值重算 air_rise，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare reduced flow with increased equipment load, tabulate temperature sensitivity, and choose sensors distinguishing bypass flow from a genuine load increase. Also recalculate air_rise for the alternative heat value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：濾網堵塞或風道短路會降低有效冷卻，即使總風機轉速正常；散熱器積塵也可能提高晶片溫度而房間平均值不變。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A blocked filter or airflow bypass reduces effective cooling despite normal fan speed; dusty heat sinks can raise chip temperature without changing the room average. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"同時量送風量、進出口溫度和設備用電，沿機櫃高度布置測點，確認冷風沒有直接繞過設備流回出口。 同步量測進出風溫度、流量和耗電，另記濕度與新風比例，確認顯熱邊界一致。","textEn":"Measure supply flow, inlet and outlet temperatures and electrical load together, instrument cabinet height, and check that cold air does not bypass the equipment. Measure inlet and outlet air temperature, airflow and electricity together, separately recording humidity and outdoor-air fraction to confirm consistent sensible boundaries.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"比較降低風量與增加設備負載兩種情況，建立溫升敏感度表，再選出能辨別旁通流和真正熱負荷增加的測點。 再以本單元 heat 的對照值重算 air_rise，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare reduced flow with increased equipment load, tabulate temperature sensitivity, and choose sensors distinguishing bypass flow from a genuine load increase. Also recalculate air_rise for the alternative heat value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「通風散熱與設備溫升」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Ventilation cooling and equipment heat\"?","options":["同時量送風量、進出口溫度和設備用電，沿機櫃高度布置測點，確認冷風沒有直接繞過設備流回出口。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","風機已經啟動就能證明隧道每一處濃度同樣下降"],"optionsEn":["Measure supply flow, inlet and outlet temperatures and electrical load together, instrument cabinet height, and check that cold air does not bypass the equipment.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","A running fan proves concentration falls equally at every point in the tunnel."],"answer":0,"explanation":"同時量送風量、進出口溫度和設備用電，沿機櫃高度布置測點，確認冷風沒有直接繞過設備流回出口。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Measure supply flow, inlet and outlet temperatures and electrical load together, instrument cabinet height, and check that cold air does not bypass the equipment. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b304-v16-04","title":"通風散熱與設備溫升：失效診斷","titleEn":"Ventilation cooling and equipment heat: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-03"],"objective":"從症狀倒推「通風散熱與設備溫升」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Ventilation cooling and equipment heat” and propose discriminating checks, corrective actions and prevention.","instruction":"濾網堵塞或風道短路會降低有效冷卻，即使總風機轉速正常；散熱器積塵也可能提高晶片溫度而房間平均值不變。 濕度升高仍可能需要更多冷量，即使乾球溫度沒有改變。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A blocked filter or airflow bypass reduces effective cooling despite normal fan speed; dusty heat sinks can raise chip temperature without changing the room average. Rising humidity can require more cooling even if the dry-bulb temperature has not changed. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把月台與車廂顯熱負載分開，避免用總冷量代替區域舒適度。","observationEn":"Link to the mechanism: Separate platform and carriage sensible loads instead of substituting total cooling for local comfort.","failure":"誤判風險：若相信「風機轉速正常就能保證機櫃內每個設備都有足夠散熱」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Normal fan speed guarantees adequate cooling for every device in the cabinet.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"濾網堵塞或風道短路會降低有效冷卻，即使總風機轉速正常；散熱器積塵也可能提高晶片溫度而房間平均值不變。 濕度升高仍可能需要更多冷量，即使乾球溫度沒有改變。","textEn":"A blocked filter or airflow bypass reduces effective cooling despite normal fan speed; dusty heat sinks can raise chip temperature without changing the room average. Rising humidity can require more cooling even if the dry-bulb temperature has not changed.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「通風散熱與設備溫升」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Ventilation cooling and equipment heat\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","濾網堵塞或風道短路會降低有效冷卻，即使總風機轉速正常；散熱器積塵也可能提高晶片溫度而房間平均值不變。","只要平均班距減半所有乘客的等待時間就一定減半"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","A blocked filter or airflow bypass reduces effective cooling despite normal fan speed.","Halving average headway necessarily halves the waiting time of every passenger."],"answer":1,"explanation":"濾網堵塞或風道短路會降低有效冷卻，即使總風機轉速正常；散熱器積塵也可能提高晶片溫度而房間平均值不變。 需以量測區分可能原因。","explanationEn":"A blocked filter or airflow bypass reduces effective cooling despite normal fan speed; dusty heat sinks can raise chip temperature without changing the room average. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b304-v16-05","title":"班距與有效運能：機制與系統路徑","titleEn":"Headway and usable capacity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-04"],"objective":"說明「班距與有效運能」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Headway and usable capacity” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"每小時運能由列車可用容量與通過頻率共同決定，平均班距縮短不代表每個車站都能吸收人流。車門交換、轉乘尖峰與不均勻到站會讓理論運能無法實現，容量計算應同時報告負載分布。 此式計算的是通過指定斷面的名目服務率，不能表示月台能容納多少人。需求在空間或時間上集中時，某站可以過載，即使整條線的平均載客率仍低。 在同一尖峰小時比較編組容量與實際逐車廂載客量。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「班距與有效運能」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Hourly capacity combines usable train capacity with passage frequency. A shorter average headway does not ensure every station can absorb the passenger flow. Door exchange, transfer surges and irregular arrivals can prevent the theoretical rate from being realised, so occupancy distribution must accompany the capacity estimate. This expression estimates a nominal service rate across a specified section, not how many people a platform can hold. Concentrated demand can overload one station even when average occupancy across the complete line remains relatively low. Compare nominal train capacity with actual per-car loading within one peak hour. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Headway and usable capacity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：people=900 persons/train; headway=185.4 s/train；計算：capacity=3600*people/headway=17475.73 persons/hour。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=900 persons/train; headway=185.4 s/train; calculation: capacity=3600*people/headway=17475.73 persons/hour.","failure":"常見誤解：「只要平均班距減半所有乘客的等待時間就一定減半」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Halving average headway necessarily halves the waiting time of every passenger.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「班距與有效運能」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Headway and usable capacity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-05-k1","title":"班距與有效運能","titleEn":"Headway and usable capacity","text":"每小時運能由列車可用容量與通過頻率共同決定，平均班距縮短不代表每個車站都能吸收人流。車門交換、轉乘尖峰與不均勻到站會讓理論運能無法實現，容量計算應同時報告負載分布。","textEn":"Hourly capacity combines usable train capacity with passage frequency. A shorter average headway does not ensure every station can absorb the passenger flow.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要平均班距減半所有乘客的等待時間就一定減半 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Halving average headway necessarily halves the waiting time of every passenger. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「班距與有效運能」，下列哪一項敘述正確？","questionEn":"Which statement about \"Headway and usable capacity\" is correct?","options":["只要平均班距減半所有乘客的等待時間就一定減半","每扇門的平均流率相同就能忽略乘客分布差異","每小時運能由列車可用容量與通過頻率共同決定，平均班距縮短不代表每個車站都能吸收人流。"],"optionsEn":["Halving average headway necessarily halves the waiting time of every passenger.","Equal average door flow rates make passenger distribution irrelevant to dwell time.","Hourly capacity combines usable train capacity with passage frequency."],"answer":2,"explanation":"每小時運能由列車可用容量與通過頻率共同決定，平均班距縮短不代表每個車站都能吸收人流。 其餘選項是常見誤解。","explanationEn":"Hourly capacity combines usable train capacity with passage frequency. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b304-v16-06","title":"班距與有效運能：定量估算","titleEn":"Headway and usable capacity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-05"],"objective":"以數值模型估算「班距與有效運能」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Headway and usable capacity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：people=900 persons/train; headway=185.4 s/train；計算：capacity=3600*people/headway=17475.73 persons/hour。敏感度：headway 單獨增加百分之十至 203.94 s/train，其餘固定，結果為 15887.03 persons/hour。模型邊界：固定班距且每列都能使用指定容量；不包含站台壅塞及服務波動。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=900 persons/train; headway=185.4 s/train; calculation: capacity=3600*people/headway=17475.73 persons/hour. Sensitivity: headway, increase this input alone by ten percent, to 203.94 s/train, with all other inputs fixed, gives 15887.03 persons/hour. Model boundary: Fixed headway with the stated usable capacity on every train; platform congestion and service variability are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以連續列車的實際到站時間與逐車廂乘載量重算，將未登車人數保留在隊列，不以列車額定容量代替實際服務量。","observationEn":"How to cross-check: Recalculate from consecutive arrival times and individual car loads.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：people=900 persons/train; headway=185.4 s/train；計算：capacity=3600*people/headway=17475.73 persons/hour。敏感度：headway 單獨增加百分之十至 203.94 s/train，其餘固定，結果為 15887.03 persons/hour。模型邊界：固定班距且每列都能使用指定容量；不包含站台壅塞及服務波動。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=900 persons/train; headway=185.4 s/train; calculation: capacity=3600*people/headway=17475.73 persons/hour. Sensitivity: headway, increase this input alone by ten percent, to 203.94 s/train, with all other inputs fixed, gives 15887.03 persons/hour. Model boundary: Fixed headway with the stated usable capacity on every train; platform congestion and service variability are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「班距與有效運能」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Headway and usable capacity\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：people=900 persons/train; headway=185.4 s/train。","量到變電所輸出電壓正常就代表所有列車端電壓正常","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Original hypothetical exercise.","Normal substation output voltage proves that every train receives normal voltage.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：people=900 persons/train; headway=185.4 s/train；計算：capacity=3600*people/headway=17475.73 persons/hour。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=900 persons/train; headway=185.4 s/train; calculation: capacity=3600*people/headway=17475.73 persons/hour. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b304-v16-07","title":"班距與有效運能：試驗與驗證","titleEn":"Headway and usable capacity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「班距與有效運能」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Headway and usable capacity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以連續列車的實際到站時間與逐車廂乘載量重算，將未登車人數保留在隊列，不以列車額定容量代替實際服務量。 逐列核對上車、下車與留下人數的守恆，並以同一計數時間窗比較需求和服務量。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Recalculate from consecutive arrival times and individual car loads. Carry passengers unable to board into the queue instead of treating rated capacity as delivered service. Check conservation of boarding, alighting and remaining passengers for every train, using identical counting windows for demand and delivered service. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：用一組規則班距與一組相同平均值的不規則班距，追蹤每班留下的人數，解釋理論容量與可用容量的差距。 再以本單元 headway 的對照值重算 capacity，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare regular and irregular headways with the same mean, track passengers left behind after each departure, and explain the gap between theoretical and usable capacity. Also recalculate capacity for the alternative headway value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：某一列延誤會使後車追近而前方隊列累積；只看小時平均會漏掉最擁擠列車與長等待尾端。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A delayed train lets following trains bunch while the upstream queue grows; an hourly mean hides both the fullest train and the long-wait tail. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"以連續列車的實際到站時間與逐車廂乘載量重算，將未登車人數保留在隊列，不以列車額定容量代替實際服務量。 逐列核對上車、下車與留下人數的守恆，並以同一計數時間窗比較需求和服務量。","textEn":"Recalculate from consecutive arrival times and individual car loads. Carry passengers unable to board into the queue instead of treating rated capacity as delivered service. Check conservation of boarding, alighting and remaining passengers for every train, using identical counting windows for demand and delivered service.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"用一組規則班距與一組相同平均值的不規則班距，追蹤每班留下的人數，解釋理論容量與可用容量的差距。 再以本單元 headway 的對照值重算 capacity，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare regular and irregular headways with the same mean, track passengers left behind after each departure, and explain the gap between theoretical and usable capacity. Also recalculate capacity for the alternative headway value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「班距與有效運能」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Headway and usable capacity\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","以連續列車的實際到站時間與逐車廂乘載量重算，將未登車人數保留在隊列，不以列車額定容量代替實際服務量。","備援電池開路電壓正常就能保證額定支援時間"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Recalculate from consecutive arrival times and individual car loads.","Normal open-circuit battery voltage guarantees the rated backup duration."],"answer":1,"explanation":"以連續列車的實際到站時間與逐車廂乘載量重算，將未登車人數保留在隊列，不以列車額定容量代替實際服務量。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Recalculate from consecutive arrival times and individual car loads. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b304-v16-08","title":"班距與有效運能：失效診斷","titleEn":"Headway and usable capacity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-07"],"objective":"從症狀倒推「班距與有效運能」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Headway and usable capacity” and propose discriminating checks, corrective actions and prevention.","instruction":"某一列延誤會使後車追近而前方隊列累積；只看小時平均會漏掉最擁擠列車與長等待尾端。 應查驗未登車隊列，避免把滿載通過當成需求已服務。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A delayed train lets following trains bunch while the upstream queue grows; an hourly mean hides both the fullest train and the long-wait tail. Inspect passengers left behind instead of interpreting a full passing train as demand served. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在同一尖峰小時比較編組容量與實際逐車廂載客量。","observationEn":"Link to the mechanism: Compare nominal train capacity with actual per-car loading within one peak hour.","failure":"誤判風險：若相信「只要平均班距減半所有乘客的等待時間就一定減半」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Halving average headway necessarily halves the waiting time of every passenger.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"某一列延誤會使後車追近而前方隊列累積；只看小時平均會漏掉最擁擠列車與長等待尾端。 應查驗未登車隊列，避免把滿載通過當成需求已服務。","textEn":"A delayed train lets following trains bunch while the upstream queue grows; an hourly mean hides both the fullest train and the long-wait tail. Inspect passengers left behind instead of interpreting a full passing train as demand served.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「班距與有效運能」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Headway and usable capacity\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","每扇門的平均流率相同就能忽略乘客分布差異","某一列延誤會使後車追近而前方隊列累積；只看小時平均會漏掉最擁擠列車與長等待尾端。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Equal average door flow rates make passenger distribution irrelevant to dwell time.","A delayed train lets following trains bunch while the upstream queue grows; an hourly mean hides both the fullest train and the long-wait tail."],"answer":2,"explanation":"某一列延誤會使後車追近而前方隊列累積；只看小時平均會漏掉最擁擠列車與長等待尾端。 需以量測區分可能原因。","explanationEn":"A delayed train lets following trains bunch while the upstream queue grows; an hourly mean hides both the fullest train and the long-wait tail. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b304-v16-s2","title":"車門交換與停站時間與電流平方損耗與散熱","titleEn":"Door exchange and dwell time & Current-squared losses and cooling","description":"本階段聚焦「車門交換與停站時間」與「電流平方損耗與散熱」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Door exchange and dwell time\" and \"Current-squared losses and cooling\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b304-v16-09","title":"車門交換與停站時間：機制與系統路徑","titleEn":"Door exchange and dwell time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-08"],"objective":"說明「車門交換與停站時間」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Door exchange and dwell time” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"停站時間由車門開關、旅客交換與確認安全三部分組成。把旅客平均分到所有車門只是基準，樓梯位置會使某幾扇門超載；最慢的門組可能控制全列發車，因此不能只用平均流率。 均分模型是檢查單位和量級的起點；真實發車須等最後必要門組完成。上車和下車方向互相干擾時，應用分階段或逐門事件模型重新識別流率。 把空調門檻造成的停留與上車交換時間分開觀測。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「車門交換與停站時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Dwell time comprises door movement, passenger exchange and confirmation before departure. Equal distribution across doors is only a baseline: stair placement can overload selected doors. The slowest door group may govern departure of the entire train, so average flow alone is insufficient. Uniform allocation is a starting point for units and scale, while actual departure waits for the last required door group. If boarding and alighting interfere, use phased or door-by-door event models to identify the relevant exchange rates. Separate hesitation near conditioned entrances from the time required for passenger exchange. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Door exchange and dwell time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s；計算：dwell=exchange/(doors*rate)+fixed=24.86458 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s; calculation: dwell=exchange/(doors*rate)+fixed=24.86458 s.","failure":"常見誤解：「每扇門的平均流率相同就能忽略乘客分布差異」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal average door flow rates make passenger distribution irrelevant to dwell time.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「車門交換與停站時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Door exchange and dwell time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-09-k1","title":"車門交換與停站時間","titleEn":"Door exchange and dwell time","text":"停站時間由車門開關、旅客交換與確認安全三部分組成。把旅客平均分到所有車門只是基準，樓梯位置會使某幾扇門超載；最慢的門組可能控制全列發車，因此不能只用平均流率。","textEn":"Dwell time comprises door movement, passenger exchange and confirmation before departure. Equal distribution across doors is only a baseline: stair placement can overload selected doors.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：每扇門的平均流率相同就能忽略乘客分布差異 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal average door flow rates make passenger distribution irrelevant to dwell time. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「車門交換與停站時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Door exchange and dwell time\" is correct?","options":["停站時間由車門開關、旅客交換與確認安全三部分組成。","每扇門的平均流率相同就能忽略乘客分布差異","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Dwell time comprises door movement, passenger exchange and confirmation before departure.","Equal average door flow rates make passenger distribution irrelevant to dwell time.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"停站時間由車門開關、旅客交換與確認安全三部分組成。 其餘選項是常見誤解。","explanationEn":"Dwell time comprises door movement, passenger exchange and confirmation before departure. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b304-v16-10","title":"車門交換與停站時間：定量估算","titleEn":"Door exchange and dwell time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-09"],"objective":"以數值模型估算「車門交換與停站時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Door exchange and dwell time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s；計算：dwell=exchange/(doors*rate)+fixed=24.86458 s。敏感度：exchange 將整數計數增加到 272至 272 persons，其餘固定，結果為 26.16667 s。模型邊界：均勻分配旅客與固定單門流率；不含對向人流衝突。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s; calculation: dwell=exchange/(doors*rate)+fixed=24.86458 s. Sensitivity: exchange, increase the integer count to 272, to 272 persons, with all other inputs fixed, gives 26.16667 s. Model boundary: Uniform passenger distribution and fixed per-door flow; opposing-flow conflicts are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：逐門標註下車、上車與關門事件，檢查樓梯附近門組是否偏慢，再以各門最大完成時間對照整列停站時間。","observationEn":"How to cross-check: Annotate alighting, boarding and closure at each door, check slow groups near stairs, and compare the latest completion time with whole-train dwell.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s；計算：dwell=exchange/(doors*rate)+fixed=24.86458 s。敏感度：exchange 將整數計數增加到 272至 272 persons，其餘固定，結果為 26.16667 s。模型邊界：均勻分配旅客與固定單門流率；不含對向人流衝突。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s; calculation: dwell=exchange/(doors*rate)+fixed=24.86458 s. Sensitivity: exchange, increase the integer count to 272, to 272 persons, with all other inputs fixed, gives 26.16667 s. Model boundary: Uniform passenger distribution and fixed per-door flow; opposing-flow conflicts are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「車門交換與停站時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Door exchange and dwell time\", which statement holds?","options":["只要列車裝有再生煞車全部動能都能回到電網","原創假想算例，全部輸入均非本工程操作參數：exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s。","風機已經啟動就能證明隧道每一處濃度同樣下降"],"optionsEn":["Installing regenerative braking returns all train kinetic energy to the supply network.","Original hypothetical exercise.","A running fan proves concentration falls equally at every point in the tunnel."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s；計算：dwell=exchange/(doors*rate)+fixed=24.86458 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: exchange=247 persons; doors=24 doors; rate=0.8 persons/(door*s); fixed=12 s; calculation: dwell=exchange/(doors*rate)+fixed=24.86458 s. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b304-v16-11","title":"車門交換與停站時間：試驗與驗證","titleEn":"Door exchange and dwell time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「車門交換與停站時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Door exchange and dwell time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"逐門標註下車、上車與關門事件，檢查樓梯附近門組是否偏慢，再以各門最大完成時間對照整列停站時間。 以影片事件時間和門控紀錄交叉對時，分別統計交換完成與發車確認的尾端分布。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Annotate alighting, boarding and closure at each door, check slow groups near stairs, and compare the latest completion time with whole-train dwell. Synchronise video event times with door-controller logs and separately report the tails of exchange completion and departure confirmation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將一半上車需求集中在四分之一車門，重算最慢門組；提出導引與月台配置改進並區分其對固定時間和交換時間的作用。 再以本單元 exchange 的對照值重算 dwell，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Concentrate half the demand at one quarter of the doors, recalculate the slowest group, and distinguish guidance changes affecting fixed time from those affecting exchange time. Also recalculate dwell for the alternative exchange value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：行李卡門或乘客集中會讓均勻模型低估尾端；延長關門提示可能改善秩序，也可能提高固定停站時間。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Luggage obstruction and clustered passengers make the uniform model underestimate the tail; a longer closing warning may improve order while increasing the fixed dwell component. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"逐門標註下車、上車與關門事件，檢查樓梯附近門組是否偏慢，再以各門最大完成時間對照整列停站時間。 以影片事件時間和門控紀錄交叉對時，分別統計交換完成與發車確認的尾端分布。","textEn":"Annotate alighting, boarding and closure at each door, check slow groups near stairs, and compare the latest completion time with whole-train dwell. Synchronise video event times with door-controller logs and separately report the tails of exchange completion and departure confirmation.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"將一半上車需求集中在四分之一車門，重算最慢門組；提出導引與月台配置改進並區分其對固定時間和交換時間的作用。 再以本單元 exchange 的對照值重算 dwell，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Concentrate half the demand at one quarter of the doors, recalculate the slowest group, and distinguish guidance changes affecting fixed time from those affecting exchange time. Also recalculate dwell for the alternative exchange value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「車門交換與停站時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Door exchange and dwell time\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","只要月台平均密度低就不會在任何局部出現壅塞","逐門標註下車、上車與關門事件，檢查樓梯附近門組是否偏慢，再以各門最大完成時間對照整列停站時間。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Low average platform density prevents congestion at every local point.","Annotate alighting, boarding and closure at each door, check slow groups near stairs, and compare the latest completion time with whole-train dwell."],"answer":2,"explanation":"逐門標註下車、上車與關門事件，檢查樓梯附近門組是否偏慢，再以各門最大完成時間對照整列停站時間。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Annotate alighting, boarding and closure at each door, check slow groups near stairs, and compare the latest completion time with whole-train dwell. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b304-v16-12","title":"車門交換與停站時間：失效診斷","titleEn":"Door exchange and dwell time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-11"],"objective":"從症狀倒推「車門交換與停站時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Door exchange and dwell time” and propose discriminating checks, corrective actions and prevention.","instruction":"行李卡門或乘客集中會讓均勻模型低估尾端；延長關門提示可能改善秩序，也可能提高固定停站時間。 先核對門口人數，避免把旅客集中誤診為門機速度下降。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Luggage obstruction and clustered passengers make the uniform model underestimate the tail; a longer closing warning may improve order while increasing the fixed dwell component. Check doorway demand before misdiagnosing passenger concentration as slower door machinery. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把空調門檻造成的停留與上車交換時間分開觀測。","observationEn":"Link to the mechanism: Separate hesitation near conditioned entrances from the time required for passenger exchange.","failure":"誤判風險：若相信「每扇門的平均流率相同就能忽略乘客分布差異」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal average door flow rates make passenger distribution irrelevant to dwell time.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"行李卡門或乘客集中會讓均勻模型低估尾端；延長關門提示可能改善秩序，也可能提高固定停站時間。 先核對門口人數，避免把旅客集中誤診為門機速度下降。","textEn":"Luggage obstruction and clustered passengers make the uniform model underestimate the tail; a longer closing warning may improve order while increasing the fixed dwell component. Check doorway demand before misdiagnosing passenger concentration as slower door machinery.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「車門交換與停站時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Door exchange and dwell time\" shows distress, which diagnosis is most reasonable?","options":["行李卡門或乘客集中會讓均勻模型低估尾端；延長關門提示可能改善秩序，也可能提高固定停站時間。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Luggage obstruction and clustered passengers make the uniform model underestimate the tail.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"行李卡門或乘客集中會讓均勻模型低估尾端；延長關門提示可能改善秩序，也可能提高固定停站時間。 需以量測區分可能原因。","explanationEn":"Luggage obstruction and clustered passengers make the uniform model underestimate the tail; a longer closing warning may improve order while increasing the fixed dwell component. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b304-v16-13","title":"電流平方損耗與散熱：機制與系統路徑","titleEn":"Current-squared losses and cooling: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-12"],"objective":"說明「電流平方損耗與散熱」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Current-squared losses and cooling” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。散熱取決於環境與接觸表面，電氣損耗量不能直接當成最終溫升。 此式是導體焦耳熱，並不是列車全部耗電。電阻會隨溫度改變，而並聯饋電使電流重新分配；比較兩方案時應保持相同功率交付邊界，避免只移轉損失位置。 分析長供電路徑的電流平方損失與午後輔助負載。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「電流平方損耗與散熱」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. Heat rejection depends on environment and contact surfaces; electrical loss alone is not a final temperature prediction. The expression represents conductor Joule heat, not all train consumption. Resistance changes with temperature, and parallel feeding redistributes current. Compare schemes at the same delivered-power boundary to avoid reporting loss relocation as an actual reduction. Examine current-squared loss on long supply paths together with afternoon auxiliary demand. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Current-squared losses and cooling” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：current=1236 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=38.1924 kW。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1236 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=38.1924 kW.","failure":"常見誤解：「用平均電流代入平方損耗公式總能得到正確熱負荷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Squaring average current always gives the correct resistive heat load.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「電流平方損耗與散熱」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Current-squared losses and cooling”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-13-k1","title":"電流平方損耗與散熱","titleEn":"Current-squared losses and cooling","text":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。散熱取決於環境與接觸表面，電氣損耗量不能直接當成最終溫升。","textEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. Heat rejection depends on environment and contact surfaces; electrical loss alone is not a final temperature prediction.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：用平均電流代入平方損耗公式總能得到正確熱負荷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Squaring average current always gives the correct resistive heat load. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「電流平方損耗與散熱」，下列哪一項敘述正確？","questionEn":"Which statement about \"Current-squared losses and cooling\" is correct?","options":["用平均電流代入平方損耗公式總能得到正確熱負荷","導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。","量到變電所輸出電壓正常就代表所有列車端電壓正常"],"optionsEn":["Squaring average current always gives the correct resistive heat load.","Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate.","Normal substation output voltage proves that every train receives normal voltage."],"answer":1,"explanation":"導體與接點的焦耳熱與電流平方成正比，短時高電流可能主導熱循環而平均電流看不出來。 其餘選項是常見誤解。","explanationEn":"Joule heating in conductors and joints scales with current squared, so short current peaks can dominate thermal cycling even when mean current looks moderate. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b304-v16-14","title":"電流平方損耗與散熱：定量估算","titleEn":"Current-squared losses and cooling: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-13"],"objective":"以數值模型估算「電流平方損耗與散熱」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Current-squared losses and cooling” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：current=1236 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=38.1924 kW。敏感度：current 單獨增加百分之十至 1359.6 A，其餘固定，結果為 46.2128 kW。模型邊界：恆定電阻且直流或等效均方根電流；不含散熱暫態。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1236 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=38.1924 kW. Sensitivity: current, increase this input alone by ten percent, to 1359.6 A, with all other inputs fixed, gives 46.2128 kW. Model boundary: Constant resistance with direct or equivalent RMS current; transient cooling is excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。","observationEn":"How to cross-check: Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：current=1236 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=38.1924 kW。敏感度：current 單獨增加百分之十至 1359.6 A，其餘固定，結果為 46.2128 kW。模型邊界：恆定電阻且直流或等效均方根電流；不含散熱暫態。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1236 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=38.1924 kW. Sensitivity: current, increase this input alone by ten percent, to 1359.6 A, with all other inputs fixed, gives 46.2128 kW. Model boundary: Constant resistance with direct or equivalent RMS current; transient cooling is excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「電流平方損耗與散熱」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Current-squared losses and cooling\", which statement holds?","options":["排水管截面夠大就不需要檢查入口堵塞及下游水位","備援電池開路電壓正常就能保證額定支援時間","原創假想算例，全部輸入均非本工程操作參數：current=1236 A; resistance=0.025 ohm。"],"optionsEn":["A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","Normal open-circuit battery voltage guarantees the rated backup duration.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：current=1236 A; resistance=0.025 ohm；計算：loss=current*current*resistance/1000=38.1924 kW。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1236 A; resistance=0.025 ohm; calculation: loss=current*current*resistance/1000=38.1924 kW. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b304-v16-15","title":"電流平方損耗與散熱：試驗與驗證","titleEn":"Current-squared losses and cooling: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「電流平方損耗與散熱」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Current-squared losses and cooling” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 由電流時間歷程積分損失，量測導體溫度以校正電阻，並比對兩端功率差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Integrate losses over the current history, measure conductor temperature to correct resistance, and compare with the difference between terminal powers. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較固定電流與同平均值脈衝電流的均方根，計算兩種損耗，寫出溫度監測與電流紀錄需要同步的原因。 再以本單元 current 的對照值重算 loss，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare constant and pulsed currents with equal means, calculate their RMS losses, and explain why current and temperature records must be time-aligned. Also recalculate loss for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 由電流時間歷程積分損失，量測導體溫度以校正電阻，並比對兩端功率差。","textEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Integrate losses over the current history, measure conductor temperature to correct resistance, and compare with the difference between terminal powers.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"比較固定電流與同平均值脈衝電流的均方根，計算兩種損耗，寫出溫度監測與電流紀錄需要同步的原因。 再以本單元 current 的對照值重算 loss，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare constant and pulsed currents with equal means, calculate their RMS losses, and explain why current and temperature records must be time-aligned. Also recalculate loss for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「電流平方損耗與散熱」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Current-squared losses and cooling\"?","options":["以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。","不確定度太難估計，報告中只寫最佳值即可。","風機轉速正常就能保證機櫃內每個設備都有足夠散熱"],"optionsEn":["Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation.","Uncertainty is too hard to estimate, so the report may state only the best value.","Normal fan speed guarantees adequate cooling for every device in the cabinet."],"answer":0,"explanation":"以均方根電流而非算術平均電流求熱負荷，同步記錄接頭溫度及環境；停電隔離後才由合格人員檢查接點。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use RMS rather than arithmetic-mean current for thermal loading, log joint and ambient temperatures, and restrict physical inspection to qualified staff after isolation. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b304-v16-16","title":"電流平方損耗與散熱：失效診斷","titleEn":"Current-squared losses and cooling: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-15"],"objective":"從症狀倒推「電流平方損耗與散熱」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Current-squared losses and cooling” and propose discriminating checks, corrective actions and prevention.","instruction":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 尖峰電流不能用平均電流取代，否則平方項損失被低估。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Peak current cannot be replaced by mean current without understating losses from the squared term. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：分析長供電路徑的電流平方損失與午後輔助負載。","observationEn":"Link to the mechanism: Examine current-squared loss on long supply paths together with afternoon auxiliary demand.","failure":"誤判風險：若相信「用平均電流代入平方損耗公式總能得到正確熱負荷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Squaring average current always gives the correct resistive heat load.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 尖峰電流不能用平均電流取代，否則平方項損失被低估。","textEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Peak current cannot be replaced by mean current without understating losses from the squared term.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「電流平方損耗與散熱」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Current-squared losses and cooling\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。","量到變電所輸出電壓正常就代表所有列車端電壓正常"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Loose joints increase resistance and concentrate heating.","Normal substation output voltage proves that every train receives normal voltage."],"answer":1,"explanation":"鬆動接點會增加電阻並使熱量集中；熱像單次讀值偏低也可能只是量測時負載不高，不能否定間歇性過熱。 需以量測區分可能原因。","explanationEn":"Loose joints increase resistance and concentrate heating; a cool one-time thermal image may simply coincide with low load and cannot rule out intermittent overheating. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b304-v16-s3","title":"牽引饋線壓降與再生煞車能量與受電條件","titleEn":"Traction feeder voltage drop & Regenerative energy and receptivity","description":"本階段聚焦「牽引饋線壓降」與「再生煞車能量與受電條件」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Traction feeder voltage drop\" and \"Regenerative energy and receptivity\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b304-v16-17","title":"牽引饋線壓降：機制與系統路徑","titleEn":"Traction feeder voltage drop: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-16"],"objective":"說明「牽引饋線壓降」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Traction feeder voltage drop” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"牽引電流經導體與回流路徑產生壓降，電壓下降又可能讓定功率列車要求更大電流，形成非線性負荷互動。單一電阻模型先隔離線路損耗，再逐步引入雙端供電和多列車位置。 回路電阻必須包含饋電與回流路徑，還需說明是否納入接頭和變電站等效阻抗。電流固定是簡化；實際定功率負載在電壓降低時可能增加電流並擴大壓降。 檢查兩列列車同時加速時最遠端的受電電壓。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「牽引饋線壓降」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Current through the feeder and return path creates voltage drop. A constant-power train may draw more current as voltage falls, creating nonlinear load interaction. A single resistance model first isolates line loss before adding two-ended supply and multiple train positions. Loop resistance must include supply and return paths, with joints and substation equivalent impedance explicitly included or excluded. Fixed current is a simplification: a constant-power load can draw more current as voltage falls and thereby increase the drop. Check receiving voltage at the far end when two trains accelerate together. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Traction feeder voltage drop” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：current=1545 A; resistance=0.06 ohm；計算：drop=current*resistance=92.7 V。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1545 A; resistance=0.06 ohm; calculation: drop=current*resistance=92.7 V.","failure":"常見誤解：「量到變電所輸出電壓正常就代表所有列車端電壓正常」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Normal substation output voltage proves that every train receives normal voltage.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「牽引饋線壓降」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Traction feeder voltage drop”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-17-k1","title":"牽引饋線壓降","titleEn":"Traction feeder voltage drop","text":"牽引電流經導體與回流路徑產生壓降，電壓下降又可能讓定功率列車要求更大電流，形成非線性負荷互動。單一電阻模型先隔離線路損耗，再逐步引入雙端供電和多列車位置。","textEn":"Current through the feeder and return path creates voltage drop. A constant-power train may draw more current as voltage falls, creating nonlinear load interaction.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：量到變電所輸出電壓正常就代表所有列車端電壓正常 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Normal substation output voltage proves that every train receives normal voltage. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「牽引饋線壓降」，下列哪一項敘述正確？","questionEn":"Which statement about \"Traction feeder voltage drop\" is correct?","options":["量到變電所輸出電壓正常就代表所有列車端電壓正常","只要列車裝有再生煞車全部動能都能回到電網","牽引電流經導體與回流路徑產生壓降，電壓下降又可能讓定功率列車要求更大電流，形成非線性負荷互動。"],"optionsEn":["Normal substation output voltage proves that every train receives normal voltage.","Installing regenerative braking returns all train kinetic energy to the supply network.","Current through the feeder and return path creates voltage drop."],"answer":2,"explanation":"牽引電流經導體與回流路徑產生壓降，電壓下降又可能讓定功率列車要求更大電流，形成非線性負荷互動。 其餘選項是常見誤解。","explanationEn":"Current through the feeder and return path creates voltage drop. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b304-v16-18","title":"牽引饋線壓降：定量估算","titleEn":"Traction feeder voltage drop: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-17"],"objective":"以數值模型估算「牽引饋線壓降」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Traction feeder voltage drop” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：current=1545 A; resistance=0.06 ohm；計算：drop=current*resistance=92.7 V。敏感度：current 單獨增加百分之十至 1699.5 A，其餘固定，結果為 101.97 V。模型邊界：固定電流與集中等效電阻；不含回生、功率因數與暫態。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1545 A; resistance=0.06 ohm; calculation: drop=current*resistance=92.7 V. Sensitivity: current, increase this input alone by ten percent, to 1699.5 A, with all other inputs fixed, gives 101.97 V. Model boundary: Fixed current and lumped equivalent resistance; regeneration, power factor and transients are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步量測變電所與列車端電壓及電流，記錄列車位置，將接頭接觸電阻與導體溫度造成的變化分別辨識。","observationEn":"How to cross-check: Synchronise substation and train voltage and current measurements, log train position, and distinguish joint contact resistance from conductor-temperature changes.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：current=1545 A; resistance=0.06 ohm；計算：drop=current*resistance=92.7 V。敏感度：current 單獨增加百分之十至 1699.5 A，其餘固定，結果為 101.97 V。模型邊界：固定電流與集中等效電阻；不含回生、功率因數與暫態。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1545 A; resistance=0.06 ohm; calculation: drop=current*resistance=92.7 V. Sensitivity: current, increase this input alone by ten percent, to 1699.5 A, with all other inputs fixed, gives 101.97 V. Model boundary: Fixed current and lumped equivalent resistance; regeneration, power factor and transients are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「牽引饋線壓降」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Traction feeder voltage drop\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：current=1545 A; resistance=0.06 ohm。","風機已經啟動就能證明隧道每一處濃度同樣下降","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["Original hypothetical exercise.","A running fan proves concentration falls equally at every point in the tunnel.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：current=1545 A; resistance=0.06 ohm；計算：drop=current*resistance=92.7 V。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: current=1545 A; resistance=0.06 ohm; calculation: drop=current*resistance=92.7 V. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b304-v16-19","title":"牽引饋線壓降：試驗與驗證","titleEn":"Traction feeder voltage drop: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「牽引饋線壓降」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Traction feeder voltage drop” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步量測變電所與列車端電壓及電流，記錄列車位置，將接頭接觸電阻與導體溫度造成的變化分別辨識。 同步量測供電端與受電端電壓及回路電流，核對接線極性和設備接頭的額外壓降。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Synchronise substation and train voltage and current measurements, log train position, and distinguish joint contact resistance from conductor-temperature changes. Measure supply voltage, receiving voltage and loop current synchronously, checking polarity and extra voltage drops across equipment connections. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：加入第二列同時加速的列車，畫出共享與非共享饋線段，分段重算壓降並說明何時需改用完整潮流分析。 再以本單元 current 的對照值重算 drop，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Add a second accelerating train, distinguish shared and separate feeder sections, recalculate each drop, and explain when a complete load-flow analysis becomes necessary. Also recalculate drop for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：高阻接頭可能在總壓降看似可接受時局部過熱；把導體長度和回流路徑計算一半會系統性低估損耗。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A high-resistance joint may overheat while total drop looks modest; omitting part of the return path systematically understates resistance and losses. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"同步量測變電所與列車端電壓及電流，記錄列車位置，將接頭接觸電阻與導體溫度造成的變化分別辨識。 同步量測供電端與受電端電壓及回路電流，核對接線極性和設備接頭的額外壓降。","textEn":"Synchronise substation and train voltage and current measurements, log train position, and distinguish joint contact resistance from conductor-temperature changes. Measure supply voltage, receiving voltage and loop current synchronously, checking polarity and extra voltage drops across equipment connections.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"加入第二列同時加速的列車，畫出共享與非共享饋線段，分段重算壓降並說明何時需改用完整潮流分析。 再以本單元 current 的對照值重算 drop，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Add a second accelerating train, distinguish shared and separate feeder sections, recalculate each drop, and explain when a complete load-flow analysis becomes necessary. Also recalculate drop for the alternative current value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「牽引饋線壓降」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Traction feeder voltage drop\"?","options":["允收準則可以等看到量測數據後再決定。","同步量測變電所與列車端電壓及電流，記錄列車位置，將接頭接觸電阻與導體溫度造成的變化分別辨識。","只要平均班距減半所有乘客的等待時間就一定減半"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Synchronise substation and train voltage and current measurements, log train position, and distinguish joint contact resistance from conductor-temperature changes.","Halving average headway necessarily halves the waiting time of every passenger."],"answer":1,"explanation":"同步量測變電所與列車端電壓及電流，記錄列車位置，將接頭接觸電阻與導體溫度造成的變化分別辨識。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Synchronise substation and train voltage and current measurements, log train position, and distinguish joint contact resistance from conductor-temperature changes. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b304-v16-20","title":"牽引饋線壓降：失效診斷","titleEn":"Traction feeder voltage drop: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-19"],"objective":"從症狀倒推「牽引饋線壓降」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Traction feeder voltage drop” and propose discriminating checks, corrective actions and prevention.","instruction":"高阻接頭可能在總壓降看似可接受時局部過熱；把導體長度和回流路徑計算一半會系統性低估損耗。 需核對回流路徑，否則可能把接頭故障藏在錯估電阻中。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A high-resistance joint may overheat while total drop looks modest; omitting part of the return path systematically understates resistance and losses. Verify the return path so a faulty connection is not hidden inside an incorrect resistance estimate. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：檢查兩列列車同時加速時最遠端的受電電壓。","observationEn":"Link to the mechanism: Check receiving voltage at the far end when two trains accelerate together.","failure":"誤判風險：若相信「量到變電所輸出電壓正常就代表所有列車端電壓正常」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Normal substation output voltage proves that every train receives normal voltage.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"高阻接頭可能在總壓降看似可接受時局部過熱；把導體長度和回流路徑計算一半會系統性低估損耗。 需核對回流路徑，否則可能把接頭故障藏在錯估電阻中。","textEn":"A high-resistance joint may overheat while total drop looks modest; omitting part of the return path systematically understates resistance and losses. Verify the return path so a faulty connection is not hidden inside an incorrect resistance estimate.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「牽引饋線壓降」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Traction feeder voltage drop\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","只要列車裝有再生煞車全部動能都能回到電網","高阻接頭可能在總壓降看似可接受時局部過熱；把導體長度和回流路徑計算一半會系統性低估損耗。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Installing regenerative braking returns all train kinetic energy to the supply network.","A high-resistance joint may overheat while total drop looks modest; omitting part of the return path systematically understates resistance and losses."],"answer":2,"explanation":"高阻接頭可能在總壓降看似可接受時局部過熱；把導體長度和回流路徑計算一半會系統性低估損耗。 需以量測區分可能原因。","explanationEn":"A high-resistance joint may overheat while total drop looks modest; omitting part of the return path systematically understates resistance and losses. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b304-v16-21","title":"再生煞車能量與受電條件：機制與系統路徑","titleEn":"Regenerative energy and receptivity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-20"],"objective":"說明「再生煞車能量與受電條件」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Regenerative energy and receptivity” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。把機械可回收量和變電站收到的電量分開，才不會把理想效率當成節電實績。 效率係數應涵蓋已宣告的轉換鏈；若把網路接受率也納入，必須說明觀測時間窗。只從速度差估計可回收量，不能辨認能量流向電網、電阻或輔助設備。 以一列煞車和一列加速的時間差研究再生能量接受率。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「再生煞車能量與受電條件」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. Separating mechanically recoverable energy from electricity received at a substation prevents ideal efficiency from being reported as measured savings. The efficiency must cover a declared conversion chain. If it includes network receptivity, the observation window must be stated. A speed change alone cannot identify how energy divides among the supply network, braking resistors and auxiliary equipment. Study receptivity through the time offset between a braking and an accelerating train. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Regenerative energy and receptivity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mass=247200 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=247200 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh.","failure":"常見誤解：「只要列車裝有再生煞車全部動能都能回到電網」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Installing regenerative braking returns all train kinetic energy to the supply network.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「再生煞車能量與受電條件」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Regenerative energy and receptivity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-21-k1","title":"再生煞車能量與受電條件","titleEn":"Regenerative energy and receptivity","text":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。把機械可回收量和變電站收到的電量分開，才不會把理想效率當成節電實績。","textEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. Separating mechanically recoverable energy from electricity received at a substation prevents ideal efficiency from being reported as measured savings.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要列車裝有再生煞車全部動能都能回到電網 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Installing regenerative braking returns all train kinetic energy to the supply network. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「再生煞車能量與受電條件」，下列哪一項敘述正確？","questionEn":"Which statement about \"Regenerative energy and receptivity\" is correct?","options":["煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。","只要列車裝有再生煞車全部動能都能回到電網","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery.","Installing regenerative braking returns all train kinetic energy to the supply network.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"煞車可回收的能量上限來自列車動能，但電網是否能接受能量、逆變器效率與輔助負載會改變實際回送量。 其餘選項是常見誤解。","explanationEn":"Train kinetic energy sets an upper bound on regenerative recovery, but network receptivity, converter efficiency and auxiliary demand determine actual delivery. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b304-v16-22","title":"再生煞車能量與受電條件：定量估算","titleEn":"Regenerative energy and receptivity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-21"],"objective":"以數值模型估算「再生煞車能量與受電條件」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Regenerative energy and receptivity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mass=247200 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh。敏感度：mass 單獨增加百分之十至 271920 kg，其餘固定，結果為 15.34271 kWh。模型邊界：一次水平減速、固定總效率；不含阻力及架線電壓限制導致的截斷。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=247200 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh. Sensitivity: mass, increase this input alone by ten percent, to 271920 kg, with all other inputs fixed, gives 15.34271 kWh. Model boundary: One level deceleration with fixed overall efficiency; resistance and voltage-limited curtailment are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。","observationEn":"How to cross-check: Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mass=247200 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh。敏感度：mass 單獨增加百分之十至 271920 kg，其餘固定，結果為 15.34271 kWh。模型邊界：一次水平減速、固定總效率；不含阻力及架線電壓限制導致的截斷。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=247200 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh. Sensitivity: mass, increase this input alone by ten percent, to 271920 kg, with all other inputs fixed, gives 15.34271 kWh. Model boundary: One level deceleration with fixed overall efficiency; resistance and voltage-limited curtailment are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「再生煞車能量與受電條件」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Regenerative energy and receptivity\", which statement holds?","options":["備援電池開路電壓正常就能保證額定支援時間","原創假想算例，全部輸入均非本工程操作參數：mass=247200 kg; v=25 m/s; eta=0.65 1。","風機轉速正常就能保證機櫃內每個設備都有足夠散熱"],"optionsEn":["Normal open-circuit battery voltage guarantees the rated backup duration.","Original hypothetical exercise.","Normal fan speed guarantees adequate cooling for every device in the cabinet."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mass=247200 kg; v=25 m/s; eta=0.65 1；計算：recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mass=247200 kg; v=25 m/s; eta=0.65 1; calculation: recovered=0.5*mass*v*v*eta/3.6e6=13.94792 kWh. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b304-v16-23","title":"再生煞車能量與受電條件：試驗與驗證","titleEn":"Regenerative energy and receptivity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「再生煞車能量與受電條件」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Regenerative energy and receptivity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 檢查功率計正負方向與積分時間邊界，以能量平衡殘差確認回送量未被重複計入。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Check meter polarity and integration boundaries, then use the energy-balance residual to confirm that exported energy has not been counted twice. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較有受電列車與無受電列車兩種功率時間圖，做能量收支表，提出儲能需求並說明額定能量不等於可接受功率。 再以本單元 mass 的對照值重算 recovered，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare power traces with and without a receptive train, build an energy balance, and size an illustrative storage requirement while distinguishing energy capacity from acceptable power. Also recalculate recovered for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 檢查功率計正負方向與積分時間邊界，以能量平衡殘差確認回送量未被重複計入。","textEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Check meter polarity and integration boundaries, then use the energy-balance residual to confirm that exported energy has not been counted twice.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"比較有受電列車與無受電列車兩種功率時間圖，做能量收支表，提出儲能需求並說明額定能量不等於可接受功率。 再以本單元 mass 的對照值重算 recovered，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare power traces with and without a receptive train, build an energy balance, and size an illustrative storage requirement while distinguishing energy capacity from acceptable power. Also recalculate recovered for the alternative mass value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「再生煞車能量與受電條件」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Regenerative energy and receptivity\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","每扇門的平均流率相同就能忽略乘客分布差異","同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Equal average door flow rates make passenger distribution irrelevant to dwell time.","Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs."],"answer":2,"explanation":"同步積分直流鏈、受電端與制動電阻的功率，對照初末速度；將輔助用電和回送電量用一致符號處理。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Integrate DC-link, line-side and braking-resistor power synchronously and compare initial and final speeds, treating auxiliary consumption and exported energy with consistent signs. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b304-v16-24","title":"再生煞車能量與受電條件：失效診斷","titleEn":"Regenerative energy and receptivity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-23"],"objective":"從症狀倒推「再生煞車能量與受電條件」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Regenerative energy and receptivity” and propose discriminating checks, corrective actions and prevention.","instruction":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 若回送受限，需查架線電壓及電阻制動記錄。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. When export is curtailed, inspect line-voltage and resistor-braking records together. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以一列煞車和一列加速的時間差研究再生能量接受率。","observationEn":"Link to the mechanism: Study receptivity through the time offset between a braking and an accelerating train.","failure":"誤判風險：若相信「只要列車裝有再生煞車全部動能都能回到電網」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Installing regenerative braking returns all train kinetic energy to the supply network.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 若回送受限，需查架線電壓及電阻制動記錄。","textEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. When export is curtailed, inspect line-voltage and resistor-braking records together.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「再生煞車能量與受電條件」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Regenerative energy and receptivity\" shows distress, which diagnosis is most reasonable?","options":["鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。","只要結構還沒倒，就代表安全餘裕仍然足夠。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Without a receptive neighbouring train, voltage can rise and trigger resistor braking.","As long as the structure is still standing, its safety margin must still be adequate.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"鄰車不在受電時再生電壓可能升高而轉入電阻制動；只量逆變器端會高估真正回到供電網的能量。 需以量測區分可能原因。","explanationEn":"Without a receptive neighbouring train, voltage can rise and trigger resistor braking; measurement only at the inverter can overstate energy returned to the supply network. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b304-v16-s4","title":"集水與排水容量與隧道換氣與稀釋時間","titleEn":"Catchment inflow and drainage capacity & Tunnel air exchange and dilution time","description":"本階段聚焦「集水與排水容量」與「隧道換氣與稀釋時間」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Catchment inflow and drainage capacity\" and \"Tunnel air exchange and dilution time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b304-v16-25","title":"集水與排水容量：機制與系統路徑","titleEn":"Catchment inflow and drainage capacity: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-24"],"objective":"說明「集水與排水容量」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Catchment inflow and drainage capacity” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。 合理化流量法假定雨強與集流條件相符，面積及逕流係數也須明確。它估算峰值流率而非完整洪水歷線；抽水或蓄水設計還需對時間積分和出口條件。 把短延時暴雨與站口集水量連結，標註泵浦失效情境。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「集水與排水容量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level. Counting only track surface can omit inflow from adjacent slopes and station areas. The rational estimate assumes rainfall intensity compatible with catchment response and explicit area and runoff coefficient. It gives a peak rate, not a complete hydrograph. Pumping or storage design additionally requires time integration and outlet conditions. Link a short intense storm to entrance runoff and mark the failed-pump scenario. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Catchment inflow and drainage capacity” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.31518 m^3/s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.31518 m^3/s.","failure":"常見誤解：「排水管截面夠大就不需要檢查入口堵塞及下游水位」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「集水與排水容量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Catchment inflow and drainage capacity”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-25-k1","title":"集水與排水容量","titleEn":"Catchment inflow and drainage capacity","text":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。鐵路集水範圍若只算軌道面，會漏掉坡面與站區流入。","textEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. Actual drainage also depends on inlet blockage, pipe slope and downstream water level.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：排水管截面夠大就不需要檢查入口堵塞及下游水位 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A sufficiently large drain eliminates the need to check blocked inlets and tailwater. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「集水與排水容量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Catchment inflow and drainage capacity\" is correct?","options":["排水管截面夠大就不需要檢查入口堵塞及下游水位","短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。","風機已經啟動就能證明隧道每一處濃度同樣下降"],"optionsEn":["A sufficiently large drain eliminates the need to check blocked inlets and tailwater.","A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient.","A running fan proves concentration falls equally at every point in the tunnel."],"answer":1,"explanation":"短時逕流可先以降雨強度、集水面積和逕流係數估計，但設施排水還受入口阻塞、管線坡度與下游水位影響。 其餘選項是常見誤解。","explanationEn":"A first runoff estimate combines rainfall intensity, catchment area and runoff coefficient. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b304-v16-26","title":"集水與排水容量：定量估算","titleEn":"Catchment inflow and drainage capacity: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-25"],"objective":"以數值模型估算「集水與排水容量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Catchment inflow and drainage capacity” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.31518 m^3/s。敏感度：rain 單獨增加百分之十至 2.266e-05 m/s，其餘固定，結果為 0.346698 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.31518 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.266e-05 m/s, with all other inputs fixed, gives 0.346698 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。","observationEn":"How to cross-check: Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.31518 m^3/s。敏感度：rain 單獨增加百分之十至 2.266e-05 m/s，其餘固定，結果為 0.346698 m^3/s。模型邊界：均勻降雨的合理化法概念；不含集流時間、水文頻率分析或蓄滯。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.31518 m^3/s. Sensitivity: rain, increase this input alone by ten percent, to 2.266e-05 m/s, with all other inputs fixed, gives 0.346698 m^3/s. Model boundary: Uniform-rainfall rational-method concept; concentration time, frequency analysis and storage are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「集水與排水容量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Catchment inflow and drainage capacity\", which statement holds?","options":["只要月台平均密度低就不會在任何局部出現壅塞","只要平均班距減半所有乘客的等待時間就一定減半","原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2。"],"optionsEn":["Low average platform density prevents congestion at every local point.","Halving average headway necessarily halves the waiting time of every passenger.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2；計算：flow=coefficient*rain*area=0.31518 m^3/s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: coefficient=0.85 1; rain=2.06e-05 m/s; area=18000 m^2; calculation: flow=coefficient*rain*area=0.31518 m^3/s. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b304-v16-27","title":"集水與排水容量：試驗與驗證","titleEn":"Catchment inflow and drainage capacity: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「集水與排水容量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Catchment inflow and drainage capacity” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 核對雨量單位和有效集水邊界，量測泵浦出流與集水井水位變化，以體積守恆互證。","textEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verify rainfall units and catchment boundaries, measure pump outflow and sump-level change, and cross-check them through volume conservation.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"將部分入口視為堵塞，建立地表暫存與排出的水量表；比較增加入口和增加泵量對不同瓶頸的效果。 再以本單元 rain 的對照值重算 flow，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Block selected inlets in the scenario, tabulate surface storage and discharge, and compare additional inlets with additional pumping for different bottlenecks. Also recalculate flow for the alternative rain value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「集水與排水容量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Catchment inflow and drainage capacity\"?","options":["現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","Squaring average current always gives the correct resistive heat load."],"answer":0,"explanation":"現地核對集水分界和入口標高，以雨量、液位與泵浦運轉紀錄檢查水量收支，分開分析正常排放和下游頂托。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Check catchment boundaries and inlet elevations, use rainfall, water-level and pump logs for a balance, and distinguish normal outflow from downstream backwater. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b304-v16-28","title":"集水與排水容量：失效診斷","titleEn":"Catchment inflow and drainage capacity: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-27"],"objective":"從症狀倒推「集水與排水容量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Catchment inflow and drainage capacity” and propose discriminating checks, corrective actions and prevention.","instruction":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把短延時暴雨與站口集水量連結，標註泵浦失效情境。","observationEn":"Link to the mechanism: Link a short intense storm to entrance runoff and mark the failed-pump scenario.","failure":"誤判風險：若相信「排水管截面夠大就不需要檢查入口堵塞及下游水位」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A sufficiently large drain eliminates the need to check blocked inlets and tailwater.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 排水堵塞改變有效出流，不能只用較大泵浦銘牌值補償。","textEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Blocked drainage changes effective outflow and cannot be compensated merely by a larger pump nameplate rating.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「集水與排水容量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Catchment inflow and drainage capacity\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。","風機已經啟動就能證明隧道每一處濃度同樣下降"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause.","A running fan proves concentration falls equally at every point in the tunnel."],"answer":1,"explanation":"垃圾堵塞入口會讓理論管徑容量無法發揮；下游水位上升又可能使出口排量下降，僅加大泵浦不能解決所有原因。 需以量測區分可能原因。","explanationEn":"Blocked inlets can prevent nominal pipe capacity from being used, while rising tailwater reduces outflow; a larger pump does not resolve every cause. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b304-v16-29","title":"隧道換氣與稀釋時間：機制與系統路徑","titleEn":"Tunnel air exchange and dilution time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-28"],"objective":"說明「隧道換氣與稀釋時間」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Tunnel air exchange and dilution time” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。 完全混合且污染源已停止時，濃度以指數衰減；剩餘比例必須介於零與一。換氣率是流量除以容積，清除時間還依目標濃度而變，不能把一次換氣直接當成全部清除。 區分換氣帶走熱量與污染物稀釋所需的不同測點。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「隧道換氣與稀釋時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow. This model illustrates dilution scale and cannot establish fire evacuation tenability. For perfect mixing after the source stops, concentration decays exponentially and the remaining fraction lies between zero and one. Air-change rate is flow divided by volume, while clearance time also depends on target concentration. One air change does not mean complete removal. Distinguish measurement points for heat removal from those for contaminant dilution. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Tunnel air exchange and dilution time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=268.2623 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=268.2623 s.","failure":"常見誤解：「風機已經啟動就能證明隧道每一處濃度同樣下降」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A running fan proves concentration falls equally at every point in the tunnel.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「隧道換氣與稀釋時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Tunnel air exchange and dilution time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-29-k1","title":"隧道換氣與稀釋時間","titleEn":"Tunnel air exchange and dilution time","text":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。","textEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：風機已經啟動就能證明隧道每一處濃度同樣下降 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A running fan proves concentration falls equally at every point in the tunnel. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「隧道換氣與稀釋時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Tunnel air exchange and dilution time\" is correct?","options":["風機已經啟動就能證明隧道每一處濃度同樣下降","備援電池開路電壓正常就能保證額定支援時間","完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。"],"optionsEn":["A running fan proves concentration falls equally at every point in the tunnel.","Normal open-circuit battery voltage guarantees the rated backup duration.","A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant."],"answer":2,"explanation":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。 其餘選項是常見誤解。","explanationEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b304-v16-30","title":"隧道換氣與稀釋時間：定量估算","titleEn":"Tunnel air exchange and dilution time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-29"],"objective":"以數值模型估算「隧道換氣與稀釋時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tunnel air exchange and dilution time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=268.2623 s。敏感度：flow 單獨增加百分之十至 28.325 m^3/s，其餘固定，結果為 243.8749 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=268.2623 s. Sensitivity: flow, increase this input alone by ten percent, to 28.325 m^3/s, with all other inputs fixed, gives 243.8749 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。","observationEn":"How to cross-check: Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=268.2623 s。敏感度：flow 單獨增加百分之十至 28.325 m^3/s，其餘固定，結果為 243.8749 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=268.2623 s. Sensitivity: flow, increase this input alone by ten percent, to 28.325 m^3/s, with all other inputs fixed, gives 243.8749 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「隧道換氣與稀釋時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Tunnel air exchange and dilution time\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1。","風機轉速正常就能保證機櫃內每個設備都有足夠散熱","每扇門的平均流率相同就能忽略乘客分布差異"],"optionsEn":["Original hypothetical exercise.","Normal fan speed guarantees adequate cooling for every device in the cabinet.","Equal average door flow rates make passenger distribution irrelevant to dwell time."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=268.2623 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=25.75 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=268.2623 s. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b304-v16-31","title":"隧道換氣與稀釋時間：試驗與驗證","titleEn":"Tunnel air exchange and dilution time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「隧道換氣與稀釋時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tunnel air exchange and dilution time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。","textEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「隧道換氣與稀釋時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Tunnel air exchange and dilution time\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。","量到變電所輸出電壓正常就代表所有列車端電壓正常"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay.","Normal substation output voltage proves that every train receives normal voltage."],"answer":1,"explanation":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b304-v16-32","title":"隧道換氣與稀釋時間：失效診斷","titleEn":"Tunnel air exchange and dilution time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-31"],"objective":"從症狀倒推「隧道換氣與稀釋時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tunnel air exchange and dilution time” and propose discriminating checks, corrective actions and prevention.","instruction":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：區分換氣帶走熱量與污染物稀釋所需的不同測點。","observationEn":"Link to the mechanism: Distinguish measurement points for heat removal from those for contaminant dilution.","failure":"誤判風險：若相信「風機已經啟動就能證明隧道每一處濃度同樣下降」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A running fan proves concentration falls equally at every point in the tunnel.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。","textEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「隧道換氣與稀釋時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Tunnel air exchange and dilution time\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","備援電池開路電壓正常就能保證額定支援時間","死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Normal open-circuit battery voltage guarantees the rated backup duration.","Stagnant pockets may remain concentrated after the average falls."],"answer":2,"explanation":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 需以量測區分可能原因。","explanationEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b304-v16-s5","title":"備援電池與可維持時間與月台暫存與隊列守恆","titleEn":"Backup battery endurance & Platform storage and queue conservation","description":"本階段聚焦「備援電池與可維持時間」與「月台暫存與隊列守恆」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Backup battery endurance\" and \"Platform storage and queue conservation\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b304-v16-33","title":"備援電池與可維持時間：機制與系統路徑","titleEn":"Backup battery endurance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-32"],"objective":"說明「備援電池與可維持時間」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Backup battery endurance” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"備援電池可供負載使用的能量由額定容量、允許放電深度和轉換效率相乘，除負載功率得到理想時間。低溫、老化及啟動電流會縮短可用時間；額定安時也不能直接當成瓦時。 可用電量應扣除允許放電深度與轉換損失，負載也可能隨時間變化。銘牌容量的測試溫度和放電倍率會影響實際結果，續航計算不能取代受控放電驗證。 分開列車牽引與車站緊急負載，核對備援能源邊界。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「備援電池與可維持時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Usable backup energy combines rated energy, permitted discharge fraction and conversion efficiency. Dividing by load gives ideal endurance. Cold temperature, ageing and start-up current can shorten it; an ampere-hour rating must not be mistaken directly for watt-hours. Usable energy must account for permitted discharge depth and conversion losses, while load may vary over time. Test temperature and discharge rate influence rated capacity, so an endurance calculation cannot replace controlled discharge verification. Separate traction from station emergency loads when checking backup-energy boundaries. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Backup battery endurance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW；計算：endurance=energy*usable*eta/load=3.708 h。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW; calculation: endurance=energy*usable*eta/load=3.708 h.","failure":"常見誤解：「備援電池開路電壓正常就能保證額定支援時間」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Normal open-circuit battery voltage guarantees the rated backup duration.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「備援電池與可維持時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Backup battery endurance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-33-k1","title":"備援電池與可維持時間","titleEn":"Backup battery endurance","text":"備援電池可供負載使用的能量由額定容量、允許放電深度和轉換效率相乘，除負載功率得到理想時間。低溫、老化及啟動電流會縮短可用時間；額定安時也不能直接當成瓦時。","textEn":"Usable backup energy combines rated energy, permitted discharge fraction and conversion efficiency. Dividing by load gives ideal endurance.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：備援電池開路電壓正常就能保證額定支援時間 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Normal open-circuit battery voltage guarantees the rated backup duration. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「備援電池與可維持時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Backup battery endurance\" is correct?","options":["備援電池可供負載使用的能量由額定容量、允許放電深度和轉換效率相乘，除負載功率得到理想時間。","備援電池開路電壓正常就能保證額定支援時間","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["Usable backup energy combines rated energy, permitted discharge fraction and conversion efficiency.","Normal open-circuit battery voltage guarantees the rated backup duration.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"備援電池可供負載使用的能量由額定容量、允許放電深度和轉換效率相乘，除負載功率得到理想時間。 其餘選項是常見誤解。","explanationEn":"Usable backup energy combines rated energy, permitted discharge fraction and conversion efficiency. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b304-v16-34","title":"備援電池與可維持時間：定量估算","titleEn":"Backup battery endurance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-33"],"objective":"以數值模型估算「備援電池與可維持時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Backup battery endurance” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW；計算：endurance=energy*usable*eta/load=3.708 h。敏感度：energy 單獨增加百分之十至 22.66 kWh，其餘固定，結果為 4.0788 h。模型邊界：固定負載與額定能量；不含電池倍率效應、溫度與容量衰退。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW; calculation: endurance=energy*usable*eta/load=3.708 h. Sensitivity: energy, increase this input alone by ten percent, to 22.66 kWh, with all other inputs fixed, gives 4.0788 h. Model boundary: Constant load and nominal energy; rate effects, temperature and capacity degradation are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：定期以已知負載做受控放電，量端電壓、電流及溫度，核對控制器切離點與真正可用能量。","observationEn":"How to cross-check: Perform controlled discharges into a known load, measure voltage, current and temperature, and compare controller cutoff with actually delivered energy.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW；計算：endurance=energy*usable*eta/load=3.708 h。敏感度：energy 單獨增加百分之十至 22.66 kWh，其餘固定，結果為 4.0788 h。模型邊界：固定負載與額定能量；不含電池倍率效應、溫度與容量衰退。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW; calculation: endurance=energy*usable*eta/load=3.708 h. Sensitivity: energy, increase this input alone by ten percent, to 22.66 kWh, with all other inputs fixed, gives 4.0788 h. Model boundary: Constant load and nominal energy; rate effects, temperature and capacity degradation are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「備援電池與可維持時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Backup battery endurance\", which statement holds?","options":["只要平均班距減半所有乘客的等待時間就一定減半","原創假想算例，全部輸入均非本工程操作參數：energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW。","用平均電流代入平方損耗公式總能得到正確熱負荷"],"optionsEn":["Halving average headway necessarily halves the waiting time of every passenger.","Original hypothetical exercise.","Squaring average current always gives the correct resistive heat load."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW；計算：endurance=energy*usable*eta/load=3.708 h。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: energy=20.6 kWh; usable=0.8 1; eta=0.9 1; load=4 kW; calculation: endurance=energy*usable*eta/load=3.708 h. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b304-v16-35","title":"備援電池與可維持時間：試驗與驗證","titleEn":"Backup battery endurance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「備援電池與可維持時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Backup battery endurance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"定期以已知負載做受控放電，量端電壓、電流及溫度，核對控制器切離點與真正可用能量。 以受控負載記錄電池電壓、電流與溫度，積分可用電量，核對低壓切斷時刻。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Perform controlled discharges into a known load, measure voltage, current and temperature, and compare controller cutoff with actually delivered energy. Record battery voltage, current and temperature under controlled load, integrate usable energy, and verify the low-voltage cut-off time. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：將負載增加一成並把可用容量降為老化假設值，重新計算時間，提出量測端電壓以外必須保留的證據。 再以本單元 energy 的對照值重算 endurance，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase load and reduce usable capacity for an ageing case, recalculate endurance, and identify evidence required beyond terminal-voltage readings. Also recalculate endurance for the alternative energy value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：老化電池可能有正常開路電壓卻無法承受負載；共用充電器故障也可能同時耗盡兩組名義備援。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: An aged battery may show normal open-circuit voltage yet fail under load; a shared charger fault can also deplete two nominally redundant banks. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"定期以已知負載做受控放電，量端電壓、電流及溫度，核對控制器切離點與真正可用能量。 以受控負載記錄電池電壓、電流與溫度，積分可用電量，核對低壓切斷時刻。","textEn":"Perform controlled discharges into a known load, measure voltage, current and temperature, and compare controller cutoff with actually delivered energy. Record battery voltage, current and temperature under controlled load, integrate usable energy, and verify the low-voltage cut-off time.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"將負載增加一成並把可用容量降為老化假設值，重新計算時間，提出量測端電壓以外必須保留的證據。 再以本單元 energy 的對照值重算 endurance，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase load and reduce usable capacity for an ageing case, recalculate endurance, and identify evidence required beyond terminal-voltage readings. Also recalculate endurance for the alternative energy value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「備援電池與可維持時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Backup battery endurance\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","只要列車裝有再生煞車全部動能都能回到電網","定期以已知負載做受控放電，量端電壓、電流及溫度，核對控制器切離點與真正可用能量。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Installing regenerative braking returns all train kinetic energy to the supply network.","Perform controlled discharges into a known load, measure voltage, current and temperature, and compare controller cutoff with actually delivered energy."],"answer":2,"explanation":"定期以已知負載做受控放電，量端電壓、電流及溫度，核對控制器切離點與真正可用能量。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Perform controlled discharges into a known load, measure voltage, current and temperature, and compare controller cutoff with actually delivered energy. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b304-v16-36","title":"備援電池與可維持時間：失效診斷","titleEn":"Backup battery endurance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-35"],"objective":"從症狀倒推「備援電池與可維持時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Backup battery endurance” and propose discriminating checks, corrective actions and prevention.","instruction":"老化電池可能有正常開路電壓卻無法承受負載；共用充電器故障也可能同時耗盡兩組名義備援。 電池電壓正常不代表容量足夠，需檢查負載下放電曲線。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"An aged battery may show normal open-circuit voltage yet fail under load; a shared charger fault can also deplete two nominally redundant banks. Normal open-circuit voltage does not prove sufficient capacity; inspect the loaded discharge curve. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：分開列車牽引與車站緊急負載，核對備援能源邊界。","observationEn":"Link to the mechanism: Separate traction from station emergency loads when checking backup-energy boundaries.","failure":"誤判風險：若相信「備援電池開路電壓正常就能保證額定支援時間」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Normal open-circuit battery voltage guarantees the rated backup duration.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"老化電池可能有正常開路電壓卻無法承受負載；共用充電器故障也可能同時耗盡兩組名義備援。 電池電壓正常不代表容量足夠，需檢查負載下放電曲線。","textEn":"An aged battery may show normal open-circuit voltage yet fail under load; a shared charger fault can also deplete two nominally redundant banks. Normal open-circuit voltage does not prove sufficient capacity; inspect the loaded discharge curve.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「備援電池與可維持時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Backup battery endurance\" shows distress, which diagnosis is most reasonable?","options":["老化電池可能有正常開路電壓卻無法承受負載；共用充電器故障也可能同時耗盡兩組名義備援。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","只要月台平均密度低就不會在任何局部出現壅塞"],"optionsEn":["An aged battery may show normal open-circuit voltage yet fail under load; a shared charger fault can also deplete two nominally redundant banks.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Low average platform density prevents congestion at every local point."],"answer":0,"explanation":"老化電池可能有正常開路電壓卻無法承受負載；共用充電器故障也可能同時耗盡兩組名義備援。 需以量測區分可能原因。","explanationEn":"An aged battery may show normal open-circuit voltage yet fail under load; a shared charger fault can also deplete two nominally redundant banks. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b304-v16-37","title":"月台暫存與隊列守恆：機制與系統路徑","titleEn":"Platform storage and queue conservation: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-36"],"objective":"說明「月台暫存與隊列守恆」如何影響高雄捷運紅線的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Platform storage and queue conservation” governs forces, deformation, flow or signals in “Kaohsiung MRT Red Line”, and map the relevant inputs, transfer paths and boundaries.","instruction":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。可用面積應扣除樓梯口、設備與安全帶；密度只能描述平均狀態，不能單獨代表行人動態風險。 密度是人數除以有效面積，不直接描述人群流速或推擠力。設備、柱子及候車線會減少可用空間；安全通道應另列，不能為了降低平均密度而計入不可占用區域。 將臨時停駛造成的累積人數分配到不同月台區域。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「月台暫存與隊列守恆」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Platform population accumulates from arrivals minus boarding and exits. A short surge can grow a queue despite sufficient daily capacity. Usable area excludes stairs, equipment and safety strips. Density describes an average state but does not alone represent dynamic pedestrian risk. Density divides occupancy by usable area but does not directly describe walking speed or crowd pressure. Equipment, columns and waiting boundaries reduce usable space. Reserved circulation must be accounted separately, not included merely to lower the reported average density. Distribute passengers accumulated during a temporary suspension across platform zones. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Platform storage and queue conservation” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：people=433 persons; usable_area=350 m^2；計算：density=people/usable_area=1.237143 persons/m^2。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=433 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.237143 persons/m^2.","failure":"常見誤解：「只要月台平均密度低就不會在任何局部出現壅塞」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Low average platform density prevents congestion at every local point.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「月台暫存與隊列守恆」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Platform storage and queue conservation”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b304-v16-37-k1","title":"月台暫存與隊列守恆","titleEn":"Platform storage and queue conservation","text":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。可用面積應扣除樓梯口、設備與安全帶；密度只能描述平均狀態，不能單獨代表行人動態風險。","textEn":"Platform population accumulates from arrivals minus boarding and exits. A short surge can grow a queue despite sufficient daily capacity.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：只要月台平均密度低就不會在任何局部出現壅塞 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Low average platform density prevents congestion at every local point. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"關於「月台暫存與隊列守恆」，下列哪一項敘述正確？","questionEn":"Which statement about \"Platform storage and queue conservation\" is correct?","options":["只要月台平均密度低就不會在任何局部出現壅塞","月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。","風機轉速正常就能保證機櫃內每個設備都有足夠散熱"],"optionsEn":["Low average platform density prevents congestion at every local point.","Platform population accumulates from arrivals minus boarding and exits.","Normal fan speed guarantees adequate cooling for every device in the cabinet."],"answer":1,"explanation":"月台人數是進入、登車與離開人數的累積差，短時尖峰會使隊列成長，即使全天總運能足夠。 其餘選項是常見誤解。","explanationEn":"Platform population accumulates from arrivals minus boarding and exits. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b304-v16-38","title":"月台暫存與隊列守恆：定量估算","titleEn":"Platform storage and queue conservation: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-37"],"objective":"以數值模型估算「月台暫存與隊列守恆」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Platform storage and queue conservation” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：people=433 persons; usable_area=350 m^2；計算：density=people/usable_area=1.237143 persons/m^2。敏感度：people 將整數計數增加到 477至 477 persons，其餘固定，結果為 1.362857 persons/m^2。模型邊界：均勻平均密度；未含局部擠壓、行李和對向人流。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: people=433 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.237143 persons/m^2. Sensitivity: people, increase the integer count to 477, to 477 persons, with all other inputs fixed, gives 1.362857 persons/m^2. Model boundary: Uniform average density; local compression, luggage and opposing streams are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。","observationEn":"How to cross-check: Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b304-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：people=433 persons; usable_area=350 m^2；計算：density=people/usable_area=1.237143 persons/m^2。敏感度：people 將整數計數增加到 477至 477 persons，其餘固定，結果為 1.362857 persons/m^2。模型邊界：均勻平均密度；未含局部擠壓、行李和對向人流。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=433 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.237143 persons/m^2. Sensitivity: people, increase the integer count to 477, to 477 persons, with all other inputs fixed, gives 1.362857 persons/m^2. Model boundary: Uniform average density; local compression, luggage and opposing streams are excluded.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"依「月台暫存與隊列守恆」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Platform storage and queue conservation\", which statement holds?","options":["每扇門的平均流率相同就能忽略乘客分布差異","量到變電所輸出電壓正常就代表所有列車端電壓正常","原創假想算例，全部輸入均非本工程操作參數：people=433 persons; usable_area=350 m^2。"],"optionsEn":["Equal average door flow rates make passenger distribution irrelevant to dwell time.","Normal substation output voltage proves that every train receives normal voltage.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：people=433 persons; usable_area=350 m^2；計算：density=people/usable_area=1.237143 persons/m^2。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: people=433 persons; usable_area=350 m^2; calculation: density=people/usable_area=1.237143 persons/m^2. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b304-v16-39","title":"月台暫存與隊列守恆：試驗與驗證","titleEn":"Platform storage and queue conservation: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「月台暫存與隊列守恆」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Platform storage and queue conservation” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 以分區影片計數核對總人數，量測淨面積，並同時記錄局部瓶頸及進出流量。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Cross-check total occupancy with zonal video counts, measure net area, and record local bottlenecks and entry-exit flows simultaneously. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：模擬一列取消後兩個班距內的人數變化，扣除不能站立的面積，提出分流措施並比較它們改變的是流量還是暫存容量。 再以本單元 people 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Simulate population for two headways after one cancellation, subtract unusable area, and compare whether proposed controls change flow rate or storage capacity. Also recalculate density for the alternative people value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b304-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 以分區影片計數核對總人數，量測淨面積，並同時記錄局部瓶頸及進出流量。","textEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Cross-check total occupancy with zonal video counts, measure net area, and record local bottlenecks and entry-exit flows simultaneously.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"模擬一列取消後兩個班距內的人數變化，扣除不能站立的面積，提出分流措施並比較它們改變的是流量還是暫存容量。 再以本單元 people 的對照值重算 density，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Simulate population for two headways after one cancellation, subtract unusable area, and compare whether proposed controls change flow rate or storage capacity. Also recalculate density for the alternative people value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"要驗證「月台暫存與隊列守恆」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Platform storage and queue conservation\"?","options":["用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。","不確定度太難估計，報告中只寫最佳值即可。","排水管截面夠大就不需要檢查入口堵塞及下游水位"],"optionsEn":["Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow.","Uncertainty is too hard to estimate, so the report may state only the best value.","A sufficiently large drain eliminates the need to check blocked inlets and tailwater."],"answer":0,"explanation":"用匿名計數器核對入口、出口與登車量，分區觀察月台密度，保留列車延誤時間以辨認隊列成長來源。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconcile anonymous counts at entrances, exits and train doors, observe density by zone, and retain train-delay times to identify why queues grow. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b304-v16-40","title":"月台暫存與隊列守恆：失效診斷","titleEn":"Platform storage and queue conservation: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"prerequisiteIds":["b304-v16-39"],"objective":"從症狀倒推「月台暫存與隊列守恆」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Platform storage and queue conservation” and propose discriminating checks, corrective actions and prevention.","instruction":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 總平均密度低仍可能局部壅塞，須查看門口與樓梯區域。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Low overall mean density can coexist with local crowding; inspect doorway and stair zones. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將臨時停駛造成的累積人數分配到不同月台區域。","observationEn":"Link to the mechanism: Distribute passengers accumulated during a temporary suspension across platform zones.","failure":"誤判風險：若相信「只要月台平均密度低就不會在任何局部出現壅塞」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Low average platform density prevents congestion at every local point.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b304-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 總平均密度低仍可能局部壅塞，須查看門口與樓梯區域。","textEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Low overall mean density can coexist with local crowding; inspect doorway and stair zones.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]},{"id":"b304-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"]}],"quiz":{"question":"在「月台暫存與隊列守恆」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Platform storage and queue conservation\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。","風機轉速正常就能保證機櫃內每個設備都有足夠散熱"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing.","Normal fan speed guarantees adequate cooling for every device in the cabinet."],"answer":1,"explanation":"平均密度低仍可能在樓梯出口形成局部瓶頸；計數器漏記同行群體也會使守恆帳不閉合。 需以量測區分可能原因。","explanationEn":"A low mean density can coexist with a bottleneck at a stair exit; missed group entries can also prevent the passenger balance from closing. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-b304-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b304-zh.svg","flowDiagramEn":"assets/diagrams/v16-b304-en.svg"}};
